          howItWorksDescription: 'ඔබේ සහකරුගේ/සහකාරියගේ පෞද්ගලිකත්වයට ගරු කරමින් ඇයට සහාය වීමට යෙදුම ඔබට ඉඩ දෙන ආකාරය දැනගන්න.',
          howItWorksParagraph1: 'AWA එක්ව ඔබට ඔබේ සහකරු/සහකාරිය ඔබ සමඟ බෙදාගැනීමට තෝරාගත් තොරතුරු පමණක් බැලීමට ඉඩ දෙයි.',
          howItWorksParagraph2: 'උදාහරණයක් ලෙස, බෙදාගැනීම සක්‍රීය කර ඇති විට, ඇයගේ චක්‍රය, ඇයගේ ඊළඟ ඔසප් හෝ ඇයගේ සාරවත් කාලය පිළිබඳ සමහර තොරතුරු ඔබට දැකිය හැක.',
          howItWorksParagraph3: 'දැකිය හැකි තොරතුරු සෑම විටම රඳා පවතින්නේ ඇයගේ තේරීම් මතය. ඇයට ඇය බෙදාගන්නා දේ ඕනෑම වේලාවක වෙනස් කළ හැක.',
