          hiddenInfoDescription: 'ඔබේ සහකරු/සහකාරිය ඇය ඔබ සමඟ බෙදාගන්නා දේ තෝරයි. ඇයට මෙම තේරීම් ඕනෑම වේලාවක වෙනස් කළ හැක.',
          hiddenInfoParagraph1: 'ඔබේ සහකරු/සහකාරිය ඔබ සමඟ බෙදාගැනීමට කැමති තොරතුරු මත පාලනය රඳවාගනී.',
