          hiddenInfoParagraph3: 'ඇයගේ තේරීම් ඕනෑම වේලාවක වෙනස් විය හැක. AWA එක්ව ඔබට දැනට ප්‍රවේශය ඇති තොරතුරු පමණක් ඔබට පෙන්වයි.',
          understandingTitle: 'බෙදාගත් තොරතුරු තේරුම් ගැනීම',
          understandingDescription: 'චක්‍ර දිනය, වත්මන් අවධිය, සාරවත් කාලය, ඇස්තමේන්තුගත ඩිම්බ මෝචනය සහ ඊළඟ ඔසප් පිළිබඳ සරල පැහැදිලි කිරීම්.',
          understandingIntro: 'ඔබ සමඟ බෙදාගත් තොරතුරු අදහස් කළ හැක්කේ මෙයයි:',
          termCycleDay: 'චක්‍ර දිනය',
