          termNextPeriod: 'ඇස්තමේන්තුගත ඊළඟ ඔසප්',
          descriptionNextPeriod: 'ඇයගේ ඊළඟ ඔසප් ආරම්භයේ ඇස්තමේන්තුගත දිනය.',
