          troubleshootingParagraph1: 'සමහර තොරතුරු නොපෙන්වන්නේ නම්, මුලින්ම ඔබේ අන්තර්ජාල සම්බන්ධතාව නිවැරදිව ක්‍රියා කරන්නේදැයි පරීක්ෂා කරන්න.',
          troubleshootingParagraph2: 'ඔබේ සහකරු/සහකාරිය දැනට එය බෙදාගන්නේ නැති නිසා ද සමහර තොරතුරු නොපෙනීමට ඉඩ ඇත.',
          troubleshootingParagraph3: 'ඔබට යෙදුම වසා නැවත විවෘත කිරීමටද උත්සාහ කළ හැක.',
          troubleshootingParagraph4: 'ගැටලුව දිගටම පවතී නම්, ඔබට AWA සහාය අමතා ගත හැක.',
